  kind := 'request_sent';
 elsif TG_OP = 'UPDATE' and new.status is distinct from old.status and new.status in ('accepted','declined') then
  kind := case when new.status = 'accepted' then 'request_accepted' else 'request_declined' end;
 else
  return new;
 end if;
