--
-- Name: profile_verification_checks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.profile_verification_checks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    verification_id uuid,
    role text NOT NULL,
    check_type text NOT NULL,
    target_key text NOT NULL,
    target_label text NOT NULL,
    target_value text,
    status text NOT NULL,
    score integer DEFAULT 0 NOT NULL,
    message text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    passport_claim boolean DEFAULT false NOT NULL,
    claim_kind text,
    claim_version integer,
    claim_value_hash text,
    passport_state text,
    submitted_at timestamp with time zone,
    decided_at timestamp with time zone,
    expires_at timestamp with time zone,
    decision_actor uuid,
    source_kind text,
    CONSTRAINT passport_claim_shape CHECK ((((NOT passport_claim) AND (claim_kind IS NULL) AND (claim_version IS NULL) AND (claim_value_hash IS NULL) AND (passport_state IS NULL) AND (submitted_at IS NULL) AND (decided_at IS NULL) AND (expires_at IS NULL) AND (decision_actor IS NULL) AND (source_kind IS NULL)) OR (passport_claim AND (verification_id IS NOT NULL) AND (role = ANY (ARRAY['early-stage-founder'::text, 'investor'::text])) AND (claim_kind IS NOT NULL) AND (claim_kind = ANY (ARRAY['account_control'::text, 'professional'::text, 'education'::text, 'startup'::text, 'firm'::text, 'traction'::text, 'investment_history'::text])) AND (claim_version IS NOT NULL) AND (claim_version > 0) AND (claim_value_hash IS NOT NULL) AND (claim_value_hash ~ '^[a-f0-9]{64}$'::text) AND (passport_state IS NOT NULL) AND (passport_state = ANY (ARRAY['submitted'::text, 'in_review'::text, 'supported'::text, 'needs_changes'::text, 'rejected'::text, 'stale'::text, 'revoked'::text, 'expired'::text])) AND (submitted_at IS NOT NULL) AND (status = 'skipped'::text) AND (score = 0) AND ((passport_state <> ALL (ARRAY['supported'::text, 'needs_changes'::text, 'rejected'::text])) OR ((decision_actor IS NOT NULL) AND (decided_at IS NOT NULL) AND (decision_actor <> user_id) AND (source_kind IS NOT NULL))) AND ((passport_state <> 'supported'::text) OR ((expires_at IS NOT NULL) AND (expires_at > decided_at))) AND ((source_kind IS NULL) OR (source_kind = ANY (ARRAY['manual_evidence'::text, 'authoritative_source'::text, 'oauth_control'::text, 'email_control'::text])))))),
    CONSTRAINT passport_payload_minimal CHECK (((NOT passport_claim) OR ((target_value IS NULL) AND (metadata = '{}'::jsonb) AND (message IS NULL)))),
    CONSTRAINT profile_verification_checks_score_check CHECK (((score >= 0) AND (score <= 100))),
    CONSTRAINT profile_verification_checks_status_check CHECK ((status = ANY (ARRAY['passed'::text, 'failed'::text, 'warning'::text, 'skipped'::text])))
);


